const R = require('ramda');
const WryError = require('../wryError');

module.exports = {
  name: 'serial',
  func: function (...tasks) {
    tasks = R.flatten(tasks);

    tasks.forEach(task => {
      if (!task || typeof task.resolve !== 'function' || typeof task.graphs !== 'object')
        throw new WryError('task is not a Wry.Continue style promise');
    });

    return {
      func: async function (files) {
        const outputs = [];

        for (let task of tasks) {
          const output = await task.resolve(files);
          outputs.push(...output);
        }

        return outputs;
      },
      graph: {
        children: tasks.map(task => task.graphs)
      }
    }
  }
};